from (values
  ('quote', 'Waste no more time arguing about what a good man should be. Be one.', 'Marcus Aurelius', array['action', 'motivation']::text[]),
  ('quote', 'Loss is nothing else but change, and change is Nature''s delight.', 'Marcus Aurelius', array['grief', 'change']::text[]),
