  ('tip', 'Ask for help with one piece of the pile, and be specific about which.', null, array['overwhelm', 'communication']::text[]),
  ('tip', 'Before bed, list three things that went well and one you''re letting go of.', null, array['sleep', 'gratitude']::text[]),
  ('tip', 'After sunset, turn your screen brightness down to match the room.', null, array['sleep', 'habits']::text[]),
  ('tip', 'Write yourself a permission slip for one evening off.', null, array['self-compassion', 'rest']::text[]),
  ('tip', 'When a harsh thought about your body shows up, name one thing it lets you do.', null, array['self-compassion', 'body']::text[]),
