  ('tip', 'Before a busy week, write down the one thing you''ll protect no matter what.', null, array['stress', 'boundaries']::text[]),
  ('tip', 'Use shoulder tension as your cue to get up and refill your water.', null, array['stress', 'habits']::text[]),
