  ('tip', 'After a bad night, keep your usual wake time anyway. It helps tomorrow night.', null, array['sleep', 'resilience']::text[]),
  ('tip', 'Plan a phone call with a friend this week and put it on both calendars.', null, array['relationships', 'planning']::text[]),
  ('tip', 'Tell someone what they mean to you, in one sentence, while they can hear it.', null, array['relationships', 'gratitude']::text[]),
  ('tip', 'Share one small worry with a friend today and let them help carry it.', null, array['relationships', 'worry']::text[]),
  ('tip', 'On Sunday, review one habit: keep it, shrink it, or swap it.', null, array['habits', 'growth']::text[]),
  ('tip', 'Pick one habit to do at the same time every day this week.', null, array['habits', 'planning']::text[]),
  ('tip', 'Leave five minutes between tasks to reset, stretch, or refill your tea.', null, array['rest', 'work']::text[]),
  ('tip', 'Write down three values and drop one commitment that fits none of them.', null, array['boundaries', 'planning']::text[]),
