insert into public.daily_content (kind, body, author, tags, min_level)
select v.kind::public.daily_kind, v.body, v.author, v.tags, 0
from (values
  ('fun_fact', 'The CDC recommends that adults get seven or more hours of sleep a night.', null, array['sleep']::text[]),
  ('fun_fact', 'Most vivid dreaming happens in REM sleep, and REM periods grow longer toward morning.', null, array['sleep']::text[]),
  ('fun_fact', 'Sleep helps consolidate memories, strengthening what you learned during the day.', null, array['sleep', 'memory']::text[]),
  ('fun_fact', 'Teenagers'' body clocks naturally shift later, which is one reason early mornings feel so hard for them.', null, array['sleep', 'body']::text[]),
  ('fun_fact', 'A short nap of about 20 minutes can boost alertness with less grogginess than a long one.', null, array['sleep', 'focus']::text[]),
  ('fun_fact', 'Caffeine''s half-life is roughly five hours, so an afternoon coffee can still be active at bedtime.', null, array['sleep', 'body']::text[]),
  ('fun_fact', 'Alcohol can make you drowsy at first but tends to fragment sleep in the second half of the night.', null, array['sleep']::text[]),
  ('fun_fact', 'Waking at a consistent time, even on weekends, is one of the steadiest ways to anchor your body clock.', null, array['sleep', 'habits']::text[]),
  ('fun_fact', 'Core body temperature dips as you fall asleep, which is one reason a cool bedroom tends to help.', null, array['sleep', 'body']::text[]),
  ('fun_fact', 'Morning daylight helps set your circadian rhythm, which can make it easier to fall asleep at night.', null, array['sleep', 'nature']::text[]),
  ('fun_fact', 'Cognitive behavioral therapy for insomnia, or CBT-I, is recommended as a first-line treatment for chronic insomnia.', null, array['sleep', 'therapy']::text[]),
  ('fun_fact', 'Lying awake in bed for long stretches can teach the brain to link bed with being awake.', null, array['sleep', 'habits']::text[]),
  ('fun_fact', 'After a poor night''s sleep, the amygdala tends to react more strongly, so small things can feel bigger.', null, array['sleep', 'emotions']::text[]),
  ('fun_fact', 'People who are short on sleep often underestimate how much it is affecting their performance.', null, array['sleep', 'focus']::text[]),
  ('fun_fact', 'Brief awakenings during the night are normal. Most people have several and never remember them.', null, array['sleep']::text[]),
  ('fun_fact', 'Circadian comes from Latin for ''about a day'', since your body clock runs on a roughly 24-hour cycle.', null, array['sleep', 'body']::text[]),
  ('fun_fact', 'A full sleep cycle lasts roughly 90 minutes, and a typical night includes four to six of them.', null, array['sleep']::text[]),
  ('fun_fact', 'Deep slow-wave sleep is concentrated in the first half of the night.', null, array['sleep', 'body']::text[]),
  ('fun_fact', 'Regular physical activity is linked to falling asleep faster and sleeping more deeply.', null, array['sleep', 'exercise']::text[]),
  ('fun_fact', 'Melatonin mostly signals that it is dark and nighttime. It sets timing more than it knocks you out.', null, array['sleep', 'body']::text[]),
  ('fun_fact', 'In one study, writing a to-do list before bed helped people fall asleep faster than writing about finished tasks.', null, array['sleep', 'journaling']::text[]),
  ('fun_fact', 'A warm bath or shower an hour or two before bed is linked to falling asleep a little faster.', null, array['sleep', 'soothing']::text[]),
  ('fun_fact', 'Gentle rocking helped adults fall asleep faster in small lab studies, much as it does for babies.', null, array['sleep', 'soothing']::text[]),
  ('fun_fact', 'Anxiety disorders are among the most common mental health conditions in the US, and they are highly treatable.', null, array['anxiety']::text[]),
  ('fun_fact', 'Avoiding what makes you anxious brings quick relief, but over time it tends to keep the fear going.', null, array['anxiety', 'habits']::text[]),
  ('fun_fact', 'Gradually facing feared situations, called exposure, is one of the best-supported approaches to anxiety.', null, array['anxiety', 'therapy']::text[]),
  ('fun_fact', 'Moderate arousal can sharpen performance, while too little or too much tends to hurt it.', null, array['anxiety', 'focus']::text[]),
  ('fun_fact', 'Anxiety tends to rise, peak and then ease on its own, even when you do nothing to push it away.', null, array['anxiety', 'emotions']::text[]),
  ('fun_fact', 'Breathing too fast can cause tingling or light-headedness, sensations often mistaken for something serious.', null, array['anxiety', 'breathing']::text[]),
  ('fun_fact', 'Caffeine can cause jitters and a racing heart that closely resemble anxiety.', null, array['anxiety', 'body']::text[]),
  ('fun_fact', 'The spotlight effect: people notice your slips and awkward moments far less than you think they do.', null, array['anxiety', 'confidence']::text[]),
  ('fun_fact', 'We tend to overestimate how visible our nervousness is to others. Researchers call it the illusion of transparency.', null, array['anxiety', 'confidence']::text[]),
  ('fun_fact', 'Seeking reassurance eases anxiety for a moment but often makes the urge to seek it grow stronger.', null, array['anxiety', 'habits']::text[]),
  ('fun_fact', 'Grounding exercises, like naming things you can see, hear and touch, pull attention back to the present.', null, array['anxiety', 'mindfulness']::text[]),
  ('fun_fact', 'The amygdala can start reacting to a possible threat before you are consciously aware of it.', null, array['anxiety', 'neuroscience']::text[]),
  ('fun_fact', 'After trauma, staying on high alert is common. It is the brain trying hard to keep you safe.', null, array['trauma', 'anxiety']::text[]),
  ('fun_fact', 'Self-compassion is consistently linked to lower levels of anxiety and depression.', null, array['self-compassion', 'anxiety']::text[]),
  ('fun_fact', 'Regular exercise is linked to fewer anxiety symptoms, and even single sessions can ease tension.', null, array['exercise', 'anxiety']::text[]),
  ('fun_fact', 'In one study, doing small acts of kindness helped socially anxious people feel less avoidant.', null, array['kindness', 'anxiety']::text[]),
  ('fun_fact', 'Anxiety and depression often occur together, and many treatments help with both.', null, array['anxiety', 'depression']::text[]),
  ('fun_fact', 'Worry often feels protective, which is part of why it can be so hard to set down.', null, array['worry']::text[]),
  ('fun_fact', 'Setting aside a short daily ''worry time'' is a technique used in CBT to keep worry from spilling into the whole day.', null, array['worry', 'therapy']::text[]),
  ('fun_fact', 'In one study of people with generalized anxiety, most of the things they worried about never happened.', null, array['worry', 'anxiety']::text[]),
  ('fun_fact', 'Anxious students who wrote about their worries just before an exam scored better in a well-known study.', null, array['worry', 'journaling']::text[]),
  ('fun_fact', 'Finding uncertainty hard to tolerate is one of the factors researchers most closely link to chronic worry.', null, array['worry', 'anxiety']::text[]),
  ('fun_fact', 'Worry and problem-solving feel similar, but problem-solving ends with an action and worry tends to loop.', null, array['worry', 'thoughts']::text[]),
  ('fun_fact', 'Cortisol naturally peaks shortly after you wake up. It helps get you going, not just stressed.', null, array['stress', 'body']::text[]),
  ('fun_fact', 'Short bursts of stress can sharpen focus. It is long, unrelenting stress that tends to wear the body down.', null, array['stress', 'body']::text[]),
  ('fun_fact', 'Seeing a stressful task as a challenge rather than a threat is linked to healthier heart and blood vessel responses.', null, array['stress', 'thoughts']::text[]),
  ('fun_fact', 'Under stress, many people reach out to others. Researchers call this the ''tend and befriend'' response.', null, array['stress', 'connection']::text[]),
  ('fun_fact', 'Feeling some control over a stressor tends to reduce its impact, even when the stressor itself stays the same.', null, array['stress', 'resilience']::text[]),
  ('fun_fact', 'Stress hormones can make memories harder to retrieve, which is why the mind can go blank under pressure.', null, array['stress', 'memory']::text[]),
  ('fun_fact', 'Progressive muscle relaxation, tensing and then releasing muscle groups, has decades of research behind it.', null, array['stress', 'body']::text[]),
  ('fun_fact', 'A clenched jaw and raised shoulders are common, often unnoticed, signs of stress.', null, array['stress', 'body']::text[]),
  ('fun_fact', 'Small daily hassles can add up to affect wellbeing as much as major life events, research suggests.', null, array['stress', 'mood']::text[]),
  ('fun_fact', 'The stress response evolved for brief physical threats, but it fires for emails and deadlines too.', null, array['stress', 'neuroscience']::text[]),
  ('fun_fact', 'Supportive relationships are one of the strongest buffers against the effects of stress.', null, array['stress', 'connection']::text[]),
  ('fun_fact', 'In one study, people who received more hugs were somewhat protected from stress-related colds.', null, array['stress', 'connection']::text[]),
  ('fun_fact', 'Stress narrows attention toward threats, which can make the bigger picture harder to see.', null, array['stress', 'attention']::text[]),
  ('fun_fact', 'Checking email in batches rather than constantly lowered daily stress in one experiment.', null, array['stress', 'work']::text[]),
  ('fun_fact', 'Time spent in forests is linked to lower stress measures, a practice known in Japan as forest bathing.', null, array['stress', 'nature']::text[]),
  ('fun_fact', 'Mindfulness-Based Stress Reduction was developed by Jon Kabat-Zinn in 1979 and has been widely studied since.', null, array['stress', 'mindfulness']::text[]),
  ('fun_fact', 'Yoga is linked to reduced stress and anxiety in many studies, likely through movement, breathing and focus combined.', null, array['stress', 'exercise']::text[]),
  ('fun_fact', 'Heart rate variability, the tiny changes between heartbeats, reflects how flexibly your body handles stress.', null, array['stress', 'body']::text[]),
  ('fun_fact', 'Writing briefly about your most important values has been shown to buffer stress in some studies.', null, array['stress', 'journaling']::text[]),
  ('fun_fact', 'The WHO lists depression among the leading causes of disability worldwide.', null, array['depression']::text[]),
  ('fun_fact', 'Depression is treatable. Most people improve with the right support, such as therapy.', null, array['depression', 'therapy']::text[]),
  ('fun_fact', 'Behavioral activation, scheduling small rewarding activities, is an effective therapy for depression.', null, array['depression', 'therapy']::text[]),
  ('fun_fact', 'A reduced ability to feel pleasure, called anhedonia, is a core feature of depression.', null, array['depression', 'emotions']::text[]),
  ('fun_fact', 'Depression can dull memory and concentration, and these often improve as mood lifts.', null, array['depression', 'memory']::text[]),
  ('fun_fact', 'Repeatedly going over problems, called rumination, is linked to longer episodes of low mood.', null, array['depression', 'thoughts']::text[]),
  ('fun_fact', 'Seasonal affective disorder is linked to shorter winter days and often eases as daylight returns.', null, array['depression', 'nature']::text[]),
  ('fun_fact', 'Depression is not a sign of weakness. It involves biology, psychology and life circumstances together.', null, array['depression']::text[]),
  ('fun_fact', 'Depression after a new baby can affect fathers as well as mothers.', null, array['depression', 'relationships']::text[]),
  ('fun_fact', 'Hopelessness is a common symptom of depression, which means it can lift as the depression is treated.', null, array['depression', 'thoughts']::text[]),
  ('fun_fact', 'Depression is not a normal part of aging, and older adults respond to treatment too.', null, array['depression']::text[]),
  ('fun_fact', 'Strong social connection is linked to a lower risk of depression.', null, array['depression', 'connection']::text[]),
  ('fun_fact', 'When mood is low, memories tend to come back as vague generalities rather than specific moments.', null, array['depression', 'memory']::text[]),
  ('fun_fact', 'Mindfulness-based cognitive therapy lowers the risk of relapse for people with recurring depression.', null, array['depression', 'mindfulness']::text[]),
  ('fun_fact', 'Strength training is linked to fewer depressive symptoms, not just cardio.', null, array['depression', 'exercise']::text[]),
  ('fun_fact', 'The brain is about 2% of body weight but uses roughly 20% of the body''s energy.', null, array['neuroscience', 'body']::text[]),
  ('fun_fact', 'The adult human brain contains roughly 86 billion neurons.', null, array['neuroscience']::text[]),
  ('fun_fact', 'Dopamine is tied more to wanting and anticipation than to the pleasure of having.', null, array['neuroscience', 'motivation']::text[]),
  ('fun_fact', 'The prefrontal cortex, key for planning and impulse control, keeps maturing into the mid-20s.', null, array['neuroscience']::text[]),
  ('fun_fact', 'The brain itself has no pain receptors, which is why some brain surgery can be done while a patient is awake.', null, array['neuroscience', 'body']::text[]),
  ('fun_fact', 'A region called the insula helps you sense internal signals like heartbeat and hunger, known as interoception.', null, array['neuroscience', 'body']::text[]),
  ('fun_fact', 'The brain tends to give bad news more weight than good. Researchers call it the negativity bias.', null, array['neuroscience', 'thoughts']::text[]),
  ('fun_fact', 'London taxi drivers who memorized the city''s streets showed differences in the size of their hippocampus.', null, array['neuroscience', 'memory']::text[]),
  ('fun_fact', 'Oxytocin is involved in bonding, but its effects depend heavily on context and the people involved.', null, array['neuroscience', 'relationships']::text[]),
  ('fun_fact', 'Much of what you perceive is the brain''s best prediction, constantly checked against incoming signals.', null, array['neuroscience', 'thoughts']::text[]),
  ('fun_fact', 'Regular meditation has been linked to changes in brain regions tied to attention and emotion regulation.', null, array['neuroscience', 'mindfulness']::text[]),
  ('fun_fact', 'Most fibers in the vagus nerve carry signals from the body up to the brain, not the other way around.', null, array['neuroscience', 'body']::text[]),
  ('fun_fact', 'Social approval activates the brain''s reward system in ways similar to other rewards.', null, array['neuroscience', 'connection']::text[]),
  ('fun_fact', 'Novelty triggers dopamine release, which may help explain why new experiences are so memorable.', null, array['neuroscience', 'memory']::text[]),
  ('fun_fact', 'Hearing your own name can cut through a noisy room. Psychologists call it the cocktail party effect.', null, array['neuroscience', 'attention']::text[]),
  ('fun_fact', 'Aerobic exercise was linked to a larger hippocampus, a key memory region, in older adults in one trial.', null, array['neuroscience', 'exercise']::text[]),
  ('fun_fact', 'Exercise raises BDNF, a protein that helps brain cells grow and connect.', null, array['neuroscience', 'exercise']::text[]),
  ('fun_fact', 'The gut has its own network of hundreds of millions of neurons, sometimes called the second brain.', null, array['neuroscience', 'body']::text[]),
  ('fun_fact', 'Rats make ultrasonic chirps when tickled, which researchers have described as a form of laughter.', null, array['neuroscience', 'humor']::text[]),
  ('fun_fact', 'Hearing laughter activates brain areas that prepare your own face to smile, one reason it is contagious.', null, array['neuroscience', 'humor']::text[]),
  ('fun_fact', 'Loneliness can make the brain more alert to social threats, which may make reaching out feel harder.', null, array['neuroscience', 'loneliness']::text[]),
  ('fun_fact', 'Compassion training changed how the brain responded to others'' distress in lab studies.', null, array['neuroscience', 'kindness']::text[]),
  ('fun_fact', 'Playing a musical instrument engages movement, hearing, memory and emotion areas at the same time.', null, array['neuroscience', 'music']::text[]),
  ('fun_fact', 'The rhythm of breathing through the nose appears to influence brain areas tied to emotion and memory.', null, array['neuroscience', 'breathing']::text[]),
  ('fun_fact', 'The two halves of the brain work together on almost everything. ''Left-brained'' personalities are a myth.', null, array['neuroscience']::text[]),
  ('fun_fact', 'Hunger can make people more irritable. Research suggests being ''hangry'' is a real effect.', null, array['body', 'anger']::text[]),
  ('fun_fact', 'Even mild dehydration is linked to lower mood and concentration in studies.', null, array['body', 'mood']::text[]),
  ('fun_fact', 'The hormone changes once claimed for ''power poses'' did not hold up in later, larger studies.', null, array['body', 'confidence']::text[]),
  ('fun_fact', 'People across cultures map emotions to strikingly similar areas of the body.', null, array['body', 'emotions']::text[]),
  ('fun_fact', 'Cold water on the face triggers the diving reflex, which slows the heart rate.', null, array['body', 'soothing']::text[]),
  ('fun_fact', 'Facial expressions may slightly influence how you feel, though the effect is smaller than once claimed.', null, array['body', 'emotions']::text[]),
  ('fun_fact', 'People sigh spontaneously every few minutes. It helps reinflate tiny air sacs in the lungs.', null, array['body', 'breathing']::text[]),
  ('fun_fact', 'Your skin has nerve fibers tuned specifically to slow, gentle stroking, which may be why soft touch soothes.', null, array['body', 'soothing']::text[]),
  ('fun_fact', 'Music-induced chills are linked to dopamine release in the brain''s reward system.', null, array['body', 'music']::text[]),
  ('fun_fact', 'Your heart speeds up slightly when you inhale and slows slightly when you exhale.', null, array['body', 'breathing']::text[]),
  ('fun_fact', 'Hospital patients with a window view of trees recovered a little faster in a classic study.', null, array['body', 'nature']::text[]),
  ('fun_fact', 'Grief can affect the body too, including sleep, appetite and concentration.', null, array['body', 'grief']::text[]),
  ('fun_fact', 'Breathing is one of the few automatic body functions you can also steer on purpose.', null, array['body', 'breathing']::text[]),
  ('fun_fact', 'A body scan, moving attention slowly through the body, is a core practice in many mindfulness programs.', null, array['body', 'mindfulness']::text[]),
  ('fun_fact', 'In Kristin Neff''s model, self-compassion has three parts: self-kindness, common humanity and mindfulness.', null, array['self-compassion']::text[]),
  ('fun_fact', 'People prompted to be self-compassionate about a mistake were more motivated to improve in several studies.', null, array['self-compassion', 'motivation']::text[]),
  ('fun_fact', 'Placing a hand on your chest is a self-compassion technique, and supportive touch may ease stress responses.', null, array['self-compassion', 'soothing']::text[]),
  ('fun_fact', 'Talking to yourself the way you would talk to a good friend is one of the simplest self-compassion exercises.', null, array['self-compassion', 'kindness']::text[]),
  ('fun_fact', 'Harsh self-criticism can feel motivating but is linked to procrastination and fear of failure.', null, array['self-compassion', 'procrastination']::text[]),
  ('fun_fact', 'Self-compassion can be learned. Structured eight-week programs have increased it in clinical trials.', null, array['self-compassion', 'mindfulness']::text[]),
  ('fun_fact', 'Students who forgave themselves for procrastinating on one exam procrastinated less on the next.', null, array['self-compassion', 'procrastination']::text[]),
  ('fun_fact', 'Missing a day barely slowed habit formation in a well-known study, so there is no need to start over.', null, array['self-compassion', 'habits']::text[]),
  ('fun_fact', 'Reminding yourself that everyone struggles, called common humanity, can make a setback feel less isolating.', null, array['self-compassion', 'loneliness']::text[]),
  ('fun_fact', 'Confidence often follows action rather than coming first. Doing builds belief.', null, array['confidence', 'motivation']::text[]),
  ('fun_fact', 'Impostor feelings are common, including among highly accomplished people.', null, array['confidence', 'work']::text[]),
  ('fun_fact', 'Psychologist Albert Bandura found that small, real successes are the strongest source of self-belief.', null, array['confidence']::text[]),
  ('fun_fact', 'After a conversation, people tend to underestimate how much the other person liked them. It''s called the liking gap.', null, array['confidence', 'connection']::text[]),
  ('fun_fact', 'Watching someone similar to you succeed can raise your belief that you can do it too.', null, array['confidence', 'motivation']::text[]),
  ('fun_fact', 'Comparing yourself to others'' online highlights is linked to lower self-evaluation in some studies.', null, array['confidence', 'mood']::text[]),
  ('fun_fact', 'Speaking to yourself by name or as ''you'' in hard moments can help you think more calmly, studies suggest.', null, array['confidence', 'thoughts']::text[]),
  ('fun_fact', 'John Gottman''s research found stable couples have about five positive interactions for every negative one in conflict.', null, array['relationships']::text[]),
  ('fun_fact', 'Responding with genuine enthusiasm to a partner''s good news is linked to stronger relationships.', null, array['relationships', 'kindness']::text[]),
  ('fun_fact', 'Couples who turn toward each other''s small bids for attention tend to be more satisfied over time.', null, array['relationships', 'connection']::text[]),
  ('fun_fact', 'Many couples therapists suggest a break of at least 20 minutes when an argument gets heated, so bodies can calm.', null, array['relationships', 'anger']::text[]),
  ('fun_fact', 'Attachment styles are not fixed. They can shift over time, especially through secure relationships.', null, array['relationships']::text[]),
  ('fun_fact', 'Feeling understood and cared for by a partner is one of the strongest predictors of relationship satisfaction.', null, array['relationships']::text[]),
  ('fun_fact', 'Gottman''s research suggests most recurring couple conflicts are ongoing differences to manage, not problems to solve.', null, array['relationships']::text[]),
  ('fun_fact', 'Trying new and exciting activities together is linked to greater relationship satisfaction.', null, array['relationships']::text[]),
  ('fun_fact', 'The bond with a therapist is one of the most consistent predictors of how well therapy works.', null, array['relationships', 'therapy']::text[]),
  ('fun_fact', 'Expressing gratitude to a partner is linked to feeling closer and more satisfied in the relationship.', null, array['relationships', 'gratitude']::text[]),
  ('fun_fact', 'Shared laughter is linked to feeling closer and more satisfied in a relationship.', null, array['relationships', 'humor']::text[]),
  ('fun_fact', 'People expect conversations with strangers to be awkward, but studies find they usually lift mood.', null, array['connection', 'mood']::text[]),
  ('fun_fact', 'People enjoy deeper conversations more than they expect to, even with strangers.', null, array['connection']::text[]),
  ('fun_fact', 'Brief friendly chats with acquaintances, like a barista or neighbor, are linked to better daily mood.', null, array['connection', 'mood']::text[]),
  ('fun_fact', 'One study estimated it takes roughly 200 hours together to turn an acquaintance into a close friend.', null, array['connection', 'relationships']::text[]),
  ('fun_fact', 'The long-running Harvard Study of Adult Development found close relationships strongly predicted later-life health and happiness.', null, array['connection', 'relationships']::text[]),
  ('fun_fact', 'Singing or moving in sync with others is linked to feeling more bonded with them.', null, array['connection', 'music']::text[]),
  ('fun_fact', 'People underestimate how much others appreciate hearing from them out of the blue.', null, array['connection', 'loneliness']::text[]),
  ('fun_fact', 'Emotions spread through groups. Moods can pass between people without anyone saying a word.', null, array['connection', 'emotions']::text[]),
  ('fun_fact', 'Teams where people feel safe to speak up and admit mistakes tend to learn and perform better.', null, array['connection', 'work']::text[]),
  ('fun_fact', 'People laugh far more often with others than alone. Laughter is mostly a social signal.', null, array['connection', 'humor']::text[]),
  ('fun_fact', 'Kindness spreads: in lab studies, people who received generosity were more likely to pass it on.', null, array['connection', 'kindness']::text[]),
  ('fun_fact', 'The US Surgeon General issued an advisory on loneliness and isolation as a public health concern in 2023.', null, array['loneliness']::text[]),
  ('fun_fact', 'Loneliness is about the gap between the connection you want and what you have, not the number of people around you.', null, array['loneliness', 'connection']::text[]),
  ('fun_fact', 'Loneliness is not just a later-life experience. Young adults report it often too.', null, array['loneliness']::text[]),
  ('fun_fact', 'Volunteering is linked to lower loneliness, possibly through purpose and regular contact.', null, array['loneliness', 'kindness']::text[]),
  ('fun_fact', 'Some researchers compare loneliness to hunger: an uncomfortable signal that nudges us toward others.', null, array['loneliness', 'emotions']::text[]),
  ('fun_fact', 'Approaches that address unhelpful thoughts about social situations tend to ease loneliness more than extra contact alone.', null, array['loneliness', 'thoughts']::text[]),
  ('fun_fact', 'Grief rarely follows neat stages. The five-stage model is not supported as a fixed sequence.', null, array['grief']::text[]),
  ('fun_fact', 'A leading model of grief says healthy grieving moves back and forth between facing the loss and taking breaks from it.', null, array['grief']::text[]),
  ('fun_fact', 'Research on bereavement finds that most people show resilience over time, even after painful losses.', null, array['grief', 'resilience']::text[]),
  ('fun_fact', 'Keeping a sense of connection to someone who died, known as continuing bonds, is common and can be healthy.', null, array['grief', 'relationships']::text[]),
  ('fun_fact', 'Grief often comes in waves, stirred by anniversaries, songs or smells.', null, array['grief', 'memory']::text[]),
  ('fun_fact', 'People grieve many losses besides death, including jobs, relationships, health and pets.', null, array['grief']::text[]),
  ('fun_fact', 'Writing a letter to someone you have lost is a technique used in grief counseling.', null, array['grief', 'journaling']::text[]),
  ('fun_fact', 'There is no correct timeline for grief. Its intensity usually softens even as love for the person stays.', null, array['grief', 'emotions']::text[]),
  ('fun_fact', 'Most people who go through a traumatic event do not develop PTSD.', null, array['trauma', 'resilience']::text[]),
  ('fun_fact', 'Many people report positive changes after struggling with adversity, which researchers call post-traumatic growth.', null, array['trauma', 'resilience']::text[]),
  ('fun_fact', 'Trauma-focused therapies such as cognitive processing therapy have strong research support.', null, array['trauma', 'therapy']::text[]),
  ('fun_fact', 'The WHO recommends EMDR therapy as one of the effective treatments for PTSD.', null, array['trauma', 'therapy']::text[]),
  ('fun_fact', 'Traumatic memories can hold vivid sensory details while their order of events feels jumbled.', null, array['trauma', 'memory']::text[]),
  ('fun_fact', 'Support from others after a traumatic event is one of the strongest protective factors for recovery.', null, array['trauma', 'connection']::text[]),
  ('fun_fact', 'The National Center for PTSD estimates about 6 in 100 people in the US will have PTSD at some point.', null, array['trauma']::text[]),
  ('fun_fact', 'The WHO classifies burnout as an occupational phenomenon, not a medical condition.', null, array['burnout', 'work']::text[]),
  ('fun_fact', 'Burnout has three parts in Christina Maslach''s model: exhaustion, cynicism and a reduced sense of effectiveness.', null, array['burnout']::text[]),
  ('fun_fact', 'Rest recharges best when you mentally detach from work, not just step away physically.', null, array['burnout', 'work']::text[]),
  ('fun_fact', 'Burnout is linked to mismatches in workload, control, reward, community, fairness and values.', null, array['burnout', 'work']::text[]),
  ('fun_fact', 'Caregivers can burn out too. Burnout is not only for paid jobs.', null, array['burnout']::text[]),
  ('fun_fact', 'Short micro-breaks during the workday are linked to more energy and less fatigue.', null, array['burnout', 'work']::text[]),
  ('fun_fact', 'The lift from a vacation often fades within weeks, suggesting regular rest matters as much as rare long breaks.', null, array['burnout', 'habits']::text[]),
  ('fun_fact', 'People in helping roles can experience compassion fatigue, a weariness from caring for others in distress.', null, array['burnout', 'kindness']::text[]),
  ('fun_fact', 'Switching between tasks has a cost. Each switch takes time and can raise the chance of errors.', null, array['work', 'focus']::text[]),
  ('fun_fact', 'Thoughts about an unfinished task can linger when you switch, a drag on focus called attention residue.', null, array['work', 'attention']::text[]),
  ('fun_fact', 'Making progress on meaningful work was the biggest day-to-day boost to workers'' mood in one diary study.', null, array['work', 'motivation']::text[]),
  ('fun_fact', 'Specific, challenging goals tend to lead to better performance than simply ''doing your best''.', null, array['work', 'motivation']::text[]),
  ('fun_fact', 'Spreading a big project across several smaller deadlines improved performance in a classic study.', null, array['work', 'procrastination']::text[]),
  ('fun_fact', 'A large analysis found perfectionism rose among young people in the US, UK and Canada over recent decades.', null, array['perfectionism']::text[]),
  ('fun_fact', 'Striving for high standards and fearing any mistake are different. The fear of mistakes is what''s linked to distress.', null, array['perfectionism']::text[]),
  ('fun_fact', 'Perfectionism and procrastination often travel together, since fear of imperfect work can delay starting.', null, array['perfectionism', 'procrastination']::text[]),
  ('fun_fact', 'People who settle on ''good enough'' choices tend to report more satisfaction than those who chase the best.', null, array['perfectionism', 'mood']::text[]),
  ('fun_fact', 'Perfectionism often runs on all-or-nothing thinking, where anything short of perfect counts as failure.', null, array['perfectionism', 'thoughts']::text[]),
  ('fun_fact', 'CBT-based approaches have reduced perfectionism in clinical trials, including self-guided versions.', null, array['perfectionism', 'therapy']::text[]),
  ('fun_fact', 'Believing others expect perfection from you is the form of perfectionism most linked to distress.', null, array['perfectionism', 'anxiety']::text[]),
  ('fun_fact', 'A small blunder can make a capable person seem more likable. Psychologists call it the pratfall effect.', null, array['perfectionism', 'connection']::text[]),
  ('fun_fact', 'Procrastination is often less about time management and more about avoiding unpleasant feelings.', null, array['procrastination', 'emotions']::text[]),
  ('fun_fact', 'Breaking a task into a tiny first step makes it easier to start.', null, array['procrastination', 'motivation']::text[]),
  ('fun_fact', 'Plans in the form ''If X happens, then I will do Y'' improve follow-through across many studies.', null, array['procrastination', 'habits']::text[]),
  ('fun_fact', 'We naturally value rewards now over rewards later, a tendency called present bias.', null, array['procrastination', 'motivation']::text[]),
  ('fun_fact', 'Brain imaging suggests people think about their future selves somewhat like strangers.', null, array['procrastination', 'thoughts']::text[]),
  ('fun_fact', 'Self-determination theory holds that motivation thrives on autonomy, competence and connection.', null, array['motivation']::text[]),
  ('fun_fact', 'Paying people for something they already enjoy can sometimes lower their interest in it.', null, array['motivation']::text[]),
  ('fun_fact', 'Effort tends to increase as a goal gets closer. Researchers call it the goal gradient effect.', null, array['motivation']::text[]),
  ('fun_fact', 'New beginnings, like a Monday or a birthday, can spark goal pursuit, a pattern called the fresh start effect.', null, array['motivation', 'habits']::text[]),
  ('fun_fact', 'Pairing a chore with something you enjoy, like a favorite podcast, is called temptation bundling.', null, array['motivation', 'habits']::text[]),
  ('fun_fact', 'Imagining your goal and then the obstacles in the way works better than positive fantasy alone.', null, array['motivation', 'thoughts']::text[]),
  ('fun_fact', 'Writing about your best possible future self has been shown to boost optimism.', null, array['motivation', 'journaling']::text[]),
  ('fun_fact', 'A sense of purpose in life is linked to greater resilience and wellbeing.', null, array['motivation', 'resilience']::text[]),
  ('fun_fact', 'A large share of everyday behavior is habit, done in the same place almost daily without much thought.', null, array['habits']::text[]),
  ('fun_fact', 'Changing your surroundings is often more effective than relying on willpower to change a habit.', null, array['habits']::text[]),
  ('fun_fact', 'Attaching a new habit to an existing routine gives it a ready-made cue.', null, array['habits']::text[]),
  ('fun_fact', 'The idea that willpower runs out like fuel has struggled to replicate in large studies.', null, array['habits', 'motivation']::text[]),
  ('fun_fact', 'Big life changes, like moving to a new place, can be a good moment to change habits because old cues disappear.', null, array['habits']::text[]),
  ('fun_fact', 'Simple habits, like drinking water with breakfast, tend to become automatic faster than complex ones.', null, array['habits']::text[]),
  ('fun_fact', 'Mindfulness is not about emptying the mind. Noticing when it wanders and returning is the practice.', null, array['mindfulness', 'attention']::text[]),
  ('fun_fact', 'Even brief mindfulness practice has improved attention in some studies.', null, array['mindfulness', 'attention']::text[]),
  ('fun_fact', 'Mindfulness can occasionally stir up difficult feelings, and shorter, gentler sessions are a fine option.', null, array['mindfulness', 'emotions']::text[]),
  ('fun_fact', 'Savoring, deliberately lingering on a good moment, tends to strengthen positive feelings.', null, array['mindfulness', 'gratitude']::text[]),
  ('fun_fact', 'Writing and delivering a thank-you letter gave people a lift in happiness that lasted weeks in one study.', null, array['gratitude', 'kindness']::text[]),
  ('fun_fact', 'In one study, counting blessings once a week boosted wellbeing more than doing it three times a week.', null, array['gratitude', 'habits']::text[]),
  ('fun_fact', 'Gratitude is linked to better sleep in some studies, possibly through more positive thoughts at bedtime.', null, array['gratitude', 'sleep']::text[]),
  ('fun_fact', 'Writing down three good things each day is a gratitude exercise studied in positive psychology.', null, array['gratitude', 'journaling']::text[]),
  ('fun_fact', 'People who kept weekly gratitude lists felt more optimistic about the coming week in a classic study.', null, array['gratitude', 'journaling']::text[]),
  ('fun_fact', 'People underestimate how good a thank-you note will make the recipient feel.', null, array['gratitude', 'kindness']::text[]),
  ('fun_fact', 'Gratitude can coexist with hard feelings. Noticing good things does not mean ignoring what is difficult.', null, array['gratitude', 'emotions']::text[]),
  ('fun_fact', 'Emotions tend to rise and fall, and rumination is one of the main things that makes them last longer.', null, array['emotions', 'thoughts']::text[]),
  ('fun_fact', 'People who describe feelings precisely, like ''disappointed'' instead of ''bad'', tend to regulate emotions better.', null, array['emotions']::text[]),
  ('fun_fact', 'Reframing a situation generally works better for wellbeing than suppressing feelings about it.', null, array['emotions', 'thoughts']::text[]),
  ('fun_fact', 'Hiding your feelings during a conversation can make it harder to remember what was said.', null, array['emotions', 'memory']::text[]),
  ('fun_fact', 'Emotional events are often remembered vividly, but vivid memories are not always accurate.', null, array['emotions', 'memory']::text[]),
  ('fun_fact', 'Awe, the feeling of being in the presence of something vast, is linked to more generosity.', null, array['emotions', 'nature']::text[]),
  ('fun_fact', 'Venting by hitting a pillow tends to fuel anger rather than release it, research finds.', null, array['anger']::text[]),
  ('fun_fact', 'Anger often shows up alongside other feelings, such as hurt, fear or embarrassment.', null, array['anger', 'emotions']::text[]),
  ('fun_fact', 'Slowing your breathing can help ease the physical surge that comes with anger.', null, array['anger', 'breathing']::text[]),
  ('fun_fact', 'Anger can be useful. It often signals that a boundary has been crossed or something feels unfair.', null, array['anger', 'emotions']::text[]),
  ('fun_fact', 'A large review found that calming activities reduce anger more reliably than venting does.', null, array['anger', 'soothing']::text[]),
  ('fun_fact', 'Anger tends to make people feel more certain and quicker to blame others, studies suggest.', null, array['anger', 'thoughts']::text[]),
  ('fun_fact', 'Anger management programs based on CBT have good research support.', null, array['anger', 'therapy']::text[]),
  ('fun_fact', 'Psychologist Ann Masten called resilience ''ordinary magic'' because it is so common.', null, array['resilience']::text[]),
  ('fun_fact', 'Resilience is not a fixed trait. Skills like problem-solving and reaching out can build it.', null, array['resilience', 'habits']::text[]),
  ('fun_fact', 'Optimism can be learned by practicing how you explain setbacks to yourself.', null, array['resilience', 'thoughts']::text[]),
  ('fun_fact', 'In one large study, people with some past adversity coped better with new stress than those with none.', null, array['resilience', 'stress']::text[]),
  ('fun_fact', 'Finding humor in hard situations is linked to better coping.', null, array['resilience', 'humor']::text[]),
  ('fun_fact', 'Writing about what you learned from a hard experience is linked to better wellbeing in several studies.', null, array['resilience', 'journaling']::text[]),
  ('fun_fact', 'The brain rarely truly multitasks. It mostly switches rapidly between tasks.', null, array['focus', 'attention']::text[]),
  ('fun_fact', 'Time in nature can refresh the ability to concentrate, an idea called attention restoration theory.', null, array['attention', 'nature']::text[]),
  ('fun_fact', 'In a famous experiment, many people counting basketball passes failed to notice a person in a gorilla suit.', null, array['attention']::text[]),
  ('fun_fact', 'People often miss large changes in a scene when their attention is elsewhere. It is called change blindness.', null, array['attention']::text[]),
  ('fun_fact', 'The popular claim that humans have a goldfish-sized eight-second attention span is not supported by research.', null, array['attention', 'focus']::text[]),
  ('fun_fact', 'Doodling while listening helped people recall more information in one study.', null, array['focus', 'memory']::text[]),
  ('fun_fact', 'Keeping your phone out of sight can make it easier to resist checking it.', null, array['focus', 'habits']::text[]),
  ('fun_fact', 'Spreading study sessions out over time leads to longer-lasting memory than cramming.', null, array['memory']::text[]),
  ('fun_fact', 'Testing yourself strengthens memory more than rereading does. It''s called the testing effect.', null, array['memory', 'habits']::text[]),
  ('fun_fact', 'Walking through a doorway can make you briefly forget what you came for, lab studies suggest.', null, array['memory', 'attention']::text[]),
  ('fun_fact', 'Tip-of-the-tongue moments are common at every age and usually resolve on their own.', null, array['memory']::text[]),
  ('fun_fact', 'Explaining something to someone else is one of the most effective ways to learn it yourself.', null, array['memory']::text[]),
  ('fun_fact', 'When you feel down, sad memories come to mind more easily. It''s called mood-congruent memory.', null, array['memory', 'mood']::text[]),
  ('fun_fact', 'Songs from your teens and early twenties tend to feel the most nostalgic, known as the reminiscence bump.', null, array['memory', 'music']::text[]),
  ('fun_fact', 'Familiar music can evoke memories even for people living with dementia.', null, array['memory', 'music']::text[]),
  ('fun_fact', 'A large study linked spending about 120 minutes a week in nature to better health and wellbeing.', null, array['nature']::text[]),
  ('fun_fact', 'Time near water, sometimes called blue space, is linked to better mood and lower stress.', null, array['nature', 'mood']::text[]),
  ('fun_fact', 'Hearing or seeing birds was linked to better mental wellbeing in a smartphone-based study.', null, array['nature', 'mood']::text[]),
  ('fun_fact', 'Most laughter follows ordinary remarks, not jokes, researchers who recorded real conversations found.', null, array['humor', 'connection']::text[]),
  ('fun_fact', 'Warm, inclusive humor is linked to wellbeing, while constantly putting yourself down is not.', null, array['humor', 'self-compassion']::text[]),
  ('fun_fact', 'Babies usually start laughing within their first few months of life.', null, array['humor']::text[]),
  ('fun_fact', 'Journaling does not need to be long. Even a few sentences can help sort through thoughts.', null, array['journaling', 'thoughts']::text[]),
  ('fun_fact', 'Putting a worry into words can make it feel more contained and less sprawling.', null, array['journaling', 'worry']::text[]),
  ('fun_fact', 'CBT is among the most thoroughly researched forms of talk therapy.', null, array['therapy']::text[]),
  ('fun_fact', 'Therapy delivered by video can be as effective as in-person therapy for many common concerns.', null, array['therapy']::text[]),
  ('fun_fact', 'Therapy is not only for crises. Many people use it to build skills and understand themselves.', null, array['therapy']::text[]),
  ('fun_fact', 'Dialectical behavior therapy teaches mindfulness, distress tolerance, emotion regulation and relationship skills.', null, array['therapy', 'emotions']::text[]),
  ('fun_fact', 'Acceptance and commitment therapy focuses on making room for hard thoughts while acting on your values.', null, array['therapy', 'thoughts']::text[]),
  ('fun_fact', 'Trying a different therapist when the fit feels off is common and perfectly okay.', null, array['therapy', 'relationships']::text[]),
  ('fun_fact', 'Music therapy is a credentialed profession in the US, practiced in hospitals, schools and clinics.', null, array['therapy', 'music']::text[]),
  ('fun_fact', 'Catastrophizing, jumping to the worst outcome, is one of the thinking patterns CBT helps people notice.', null, array['thoughts', 'therapy']::text[]),
  ('fun_fact', 'Trying hard not to think about something can make it pop up more often, the ''white bear'' effect.', null, array['thoughts', 'mindfulness']::text[]),
  ('fun_fact', 'Saying ''I''m having the thought that...'' can create a little distance from a painful thought.', null, array['thoughts', 'mindfulness']::text[]),
  ('fun_fact', 'Studies across many countries find that nearly everyone has unwanted, intrusive thoughts at times.', null, array['thoughts', 'anxiety']::text[]),
  ('fun_fact', 'Thoughts are not facts. Noticing a thought is different from believing it.', null, array['thoughts', 'mindfulness']::text[]),
  ('fun_fact', 'Getting stuck on a catchy song is so common that researchers study it. Most earworms fade on their own.', null, array['thoughts', 'music']::text[]),
  ('fun_fact', 'Stroking a friendly dog is linked to lower stress in some studies.', null, array['soothing', 'stress']::text[]),
  ('fun_fact', 'Humming naturally lengthens the exhale, which may help settle the nervous system.', null, array['soothing', 'breathing']::text[]),
  ('fun_fact', 'Listening to calming music before surgery reduced anxiety in many clinical trials.', null, array['soothing', 'music']::text[]),
  ('fun_fact', 'DBT teaches self-soothing through the five senses: sight, sound, smell, taste and touch.', null, array['soothing', 'therapy']::text[]),
  ('fun_fact', 'Activity counts in small doses. Short bouts spread through the day add up.', null, array['exercise', 'habits']::text[]),
  ('fun_fact', 'US guidelines recommend about 150 minutes of moderate activity a week for adults.', null, array['exercise', 'body']::text[]),
  ('fun_fact', 'A single session of exercise can lift mood for a while afterward.', null, array['exercise', 'mood']::text[]),
  ('fun_fact', 'Dancing combines movement, music and often connection, all linked to wellbeing.', null, array['exercise', 'music']::text[]),
  ('fun_fact', 'Sad music is often enjoyed and can feel comforting rather than upsetting.', null, array['music', 'emotions']::text[]),
