  ('fun_fact', 'Two quick inhales through the nose and one long exhale, the physiological sigh, improved mood in one study.', null, array['breathing', 'stress']::text[]),
  ('fun_fact', 'Breathing around six breaths a minute tends to maximize heart rate variability.', null, array['breathing', 'body']::text[]),
